/**
 * Draft Validator
 *
 * ref: P8-001
 *
 * Structural pre-quarantine gate for LLM-generated artifacts.
 * Stricter than validateSkillOutput because the input has no prior
 * structural guarantees — the LLM generated everything from scratch.
 *
 * Core principle: LLM generates artifact body, host generates all
 * structural metadata (revision_id, content_hash, schema_version).
 *
 * 15 checks, all deterministic:
 *   1. Top-level is an object
 *   2. artifact_type is valid
 *   3. schema_version matches type (host sets if wrong)
 *   4. artifact_id is valid snake_case
 *   5. artifact_id not colliding with existing
 *   6. sections is non-empty array
 *   7. Each section has unique section_id
 *   8. Each section has non-empty title
 *   9. Each section has ≥1 block
 *  10. All block_ids globally unique
 *  11. Each block has valid type
 *  12. Each block has non-empty text
 *  13. Each block status is draft/candidate only
 *  14. LLM revision_id/content_hash not trusted (host overwrites)
 *  15. No linked_* references to nonexistent block IDs within artifact
 */
import type { Artifact } from "./types.js";
export type DraftValidationResult = {
    status: "accepted";
    artifact: Artifact;
    warnings: string[];
} | {
    status: "rejected";
    errors: string[];
    warnings: string[];
};
/**
 * Validate a raw LLM-generated artifact and finalize it for quarantine.
 *
 * If accepted, returns a fully host-finalized Artifact:
 * - All content_hash values recomputed
 * - revision_id generated by host
 * - schema_version corrected
 * - metadata set by host
 *
 * @param raw - The parsed JSON from the LLM
 * @param existingArtifactIds - IDs of artifacts already in the store
 */
export declare function validateDraft(raw: unknown, existingArtifactIds?: string[]): DraftValidationResult;
